import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.DzNHXt93.js";const m=JSON.parse('{"title":"QueueConsumer — takoform_queue_consumer","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/queue-consumer.md","filePath":"proposals/edge/queue-consumer.md"}'),s={name:"proposals/edge/queue-consumer.md"};function n(i,e,d,c,h,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="queueconsumer-—-takoform-queue-consumer" tabindex="-1">QueueConsumer — <code>takoform_queue_consumer</code> <a class="header-anchor" href="#queueconsumer-—-takoform-queue-consumer" aria-label="Permalink to &quot;QueueConsumer — `takoform_queue_consumer`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A team wires one Module Worker as the batch consumer of one At-Least-Once Queue: the platform invokes the worker&#39;s <code>queue</code> handler with message batches and redelivers failed batches until retries are exhausted.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>attachment</code>. Queue consumption is inward activation and therefore an attachment, never a binding (decision 0010). Deleting the consumer detaches it and never deletes the queue or the worker.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p><code>queue</code> and <code>worker</code> are immutable; changing either replaces the attachment. One queue has at most one consumer, so a second attachment against the same queue is refused. Batching is bounded by <code>maxBatchSize</code> (1..100) and <code>maxBatchTimeoutSeconds</code> (0..60). A handler that returns without settling anything acknowledges the whole batch; one that throws retries every message it had not already acknowledged, after <code>retryDelaySeconds</code>. <code>maxRetries</code> counts REDELIVERIES only — the first delivery does not count toward it — so a message is delivered at most <code>1 + maxRetries</code> times; exhausted messages go to <code>deadLetterQueue</code> when declared and are dropped otherwise, and the dead-letter copy is a new message there with its own identity, its own acceptance timestamp, and an attempt count starting again at 1. <code>maxConcurrency</code> (1..250) bounds concurrent batch invocations. All of these change observable delivery behavior and are therefore desired fields, not host tuning (decision 0020).</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Retry, dead-lettering, and batch shape decide what an application observes under failure; they must travel with the consumer edge itself.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>Pull-based consumption through a client API, or push consumption with per-message acknowledgement semantics, are different shapes.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Attaching to a worker whose versions do not declare the <code>queue</code> handler must fail closed. A dead-letter queue must be a distinct queue; hosts must reject self-dead-lettering — and a cycle of any length through the dead-letter graph, because the transfer resets the attempt count and nothing else bounds the loop (<a href="./../../spec/decisions/0026-attachment-claims-are-canonical-and-acyclic.html">decision 0026</a>). Deleting the referenced queue or worker while attached must fail with <code>dependency_in_use</code>.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The queue-consumer wiring of a proven edge platform, with its retry and dead-letter semantics made explicit desired state.</p>',19)])])}const p=a(s,[["render",n]]);export{m as __pageData,p as default};
